// Pull active/open tasks from the tracker and the Next steps from the newest daily note.
const items = $input.all();
let tracker = '';
const daily = [];

for (const item of items) {
  const fileName = item.binary?.data?.fileName ?? '';
  if (fileName === '_Tracker.md') tracker = item.json.text;
  else daily.push({ fileName, text: item.json.text });
}

const tasks = tracker
  .split('\n')
  .filter((line) => /^\|\s*(active|open)\s*\|/.test(line))
  .map((line) => {
    const status = line.split('|')[1].trim();
    const note = line.match(/\[\[([^\]|\\]+)/)?.[1] ?? '';
    return { status, note, title: note.replace(/^\d{4}-\d{2}-\d{2} /, '') };
  })
  .filter((task) => task.note && task.title !== 'n8n Daily Study Briefing');

daily.sort((a, b) => a.fileName.localeCompare(b.fileName));
const latest = daily.at(-1);
const nextSteps = (latest?.text.match(/## Next steps\n([\s\S]*?)(\n## |$)/)?.[1] ?? '')
  .split('\n')
  .filter((line) => line.startsWith('- '))
  .map((line) => line.replace(/:?\s*\[\[[^\]]*\]\]/g, '').trim());

const active = tasks.filter((task) => task.status === 'active');
const open = tasks.filter((task) => task.status === 'open');

return [{
  json: {
    today: $now.toFormat('yyyy-MM-dd'),
    activeList: active.map((task) => `- ${task.title}`).join('\n') || '- (none)',
    nextStepsList: nextSteps.join('\n') || '- (none)',
    waitingOnMe: open.map((task) => `- [[${task.note}|${task.title}]]`).join('\n') || '- Nothing',
    latestDailyName: latest ? latest.fileName.replace(/\.md$/, '') : '',
  },
}];

