// Wrap the model's text in the vault's note format.
const info = $('Collect open tasks').first().json;
const body = $input.first().json.text.trim();
const links = ['- [[Tasks/_Tracker|Task Tracker]]'];
if (info.latestDailyName) links.push(`- [[${info.latestDailyName}]]`);

const content = [
  '---',
  `created: ${info.today}`,
  'type: daily',
  'tags: [briefing, n8n]',
  'status: active',
  '---',
  `# Morning Briefing ${info.today}`,
  '',
  '_Written by the n8n workflow "03 Daily Study Briefing" with llama3.2:3b. Check it against the tracker._',
  '',
  body,
  '',
  '## Waiting on me',
  info.waitingOnMe,
  '',
  '## Links',
  ...links,
  '',
].join('\n');

return [{ json: { fileName: `${info.today} Morning Briefing.md`, content } }];
